"""Gaps in opening hours where nobody is working."""

from typing import Iterable, List

from hourglass.merging import merge_spans
from hourglass.models import Span
from hourglass.parsing import format_span

# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """Label each uncovered stretch of opening hours."""
    spans = list(worked)
    _check_within(spans, opening)
    gaps = _gaps(merge_spans(spans), opening)
    return [_label(stretch) for stretch in gaps]

def _check_within(spans: List[Span], opening: Span) -> None:
    for span in spans:
        early = span.start < opening.start
        late = span.end > opening.end
        if early or late:
            text = format_span(span)
            raise ValueError(f"outside hours: {text}")

def _gaps(spans: List[Span], opening: Span) -> List[Span]:
    gaps = []
    cursor = opening.start
    for span in spans:
        gaps += _between(cursor, span.start)
        cursor = span.end
    return gaps + _between(cursor, opening.end)

def _between(start: int, stop: int) -> List[Span]:
    if start < stop:
        return [Span(start, stop)]
    return []

def _label(stretch: Span) -> str:
    text = format_span(stretch)
    return f"gap {text} ({stretch.minutes} min)"
